# Kernel-checked A-certificate: generator of the data files in ZetaIrrational/Z7/CertAK/.
# Run from the repository root:
#
#   LEAN_NUM_THREADS=8 lake build ZetaIrrational.Z7.CertAK.Windows ZetaIrrational.Z7.CertAK.FastG
#   lake env lean scripts/certA/GenCertA_Z7.lean        # #eval: writes scripts/certA/gen_Z7.txt
#   python scripts/certA/gen_certA_files.py Z7          # writes EvData, EvWin*, EvSorted, EvSum*, CertCompute
#
# The general proofs FastG/EvSort/Windows live in Z7/CertAK/ and are not generated.
# The `#eval` output is untrusted: every claim in the generated files is re-checked by `decide +kernel`.
import io, math, sys, os

INST = {
    # Z7: 30,137 events in [1, 400); windows of width 3; chunks of 32 points; 1029 chunks in 30 EvSum files
    # (6 import chains). Measured 2026-10-22: ~0.4 s per point (termUnitsG); full CertAK build 29 min wall
    # with LEAN_NUM_THREADS=12 (~2-7 min per file).
    'Z7': dict(ns='ZetaIrr.Z7.CertA', prefix='ZetaIrrational.Z7.CertAK', name='Z7',
               W=3, NW=133, CH=32, NWF=9, NWCH=3, SUMPER=36, NCH=6,
               total=778841997893779320302794447562),
}

inst = sys.argv[1] if len(sys.argv) > 1 else 'Z7'
mode = sys.argv[2] if len(sys.argv) > 2 else 'data'
C = dict(INST[inst])
for a in sys.argv[3:]:            # overrides, e.g. SUMPER=40 NCH=4
    k, v = a.split('=', 1)
    C[k] = int(v) if v.isdigit() else v
assert 1 + C['W'] * C['NW'] == 400
NS, PFX, NW, W = C['ns'], C['prefix'], C['NW'], C['W']
DEFS = C.get('defs', PFX)                # module prefix of the instance's Defs/Step (default: PFX)
D = PFX.replace('.', '/') + '/'
GENTXT = f'scripts/certA/gen_{inst}.txt'


def w(path, s):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    io.open(path, 'w', encoding='utf-8', newline='\n').write(s)


def rd(path):
    return io.open(path, encoding='utf-8').read()


if mode != 'data':
    sys.exit('only the data mode exists; the lib files and GenCertA_Z7.lean are hand-written')

# ---------------------------------------------------------------- data
assert mode == 'data', mode
lines = rd(GENTXT).strip().split('\n')
wins = []   # list of list of (value, [events])
total = None
for ln in lines:
    t = ln.split(' ')
    if t[0] == 'W':
        assert t[3] == 'true'
        wins.append([])
    elif t[0] == 'C':
        wins[-1].append((int(t[1]), t[2:]))
    elif t[0] == 'T':
        total = int(t[1])
assert len(wins) == NW
chunks = [c for wj in wins for c in wj]
assert sum(v for v, _ in chunks) == total == C['total']
NC = len(chunks)
NEV = sum(len(e) for _, e in chunks)
HDR = '''/-
# GENERATED by `scripts/certA/gen_certA_files.py` from `#eval` output — do not edit by hand.
{doc}
-/
'''
HEAD = f'\n\nnamespace {NS}\n\nset_option maxRecDepth '

# ---------- EvData ----------
out = [HDR.format(doc=f'''The {NEV:,} event points of `events 400` below `400`, as {NC} literal chunks `evC i` of at most {C['CH']}
points each, grouped by the {NW} windows `[1 + {W}j, {1 + W} + {W}j)` (`evWins`). Every claim about these lists
is checked by `decide +kernel` in `EvWin*.lean`, `EvSorted.lean` and `EvSum*.lean`.'''),
       f'import {PFX}.Windows' + HEAD + '100000\n']
for i, (v, evs) in enumerate(chunks):
    out.append(f'/-- Event chunk {i}. -/\ndef evC{i} : List ℚ := [{", ".join(evs)}]\n')
out.append('/-- All event chunks, in order. -/\ndef evChunks : List (List ℚ) :=\n  [' +
           ', '.join(f'evC{i}' for i in range(NC)) + ']\n')
k = 0
wl = []
for wj in wins:
    wl.append('[' + ', '.join(f'evC{k+t}' for t in range(len(wj))) + ']')
    k += len(wj)
out.append('/-- The event chunks of each window. -/\ndef evWins : List (List (List ℚ)) :=\n  [' +
           ',\n   '.join(wl) + ']\n')
out.append(f'lemma evWins_length : evWins.length = {NW} := rfl\n')
out.append('lemma evWins_flatten : evWins.flatten = evChunks := rfl\n')
out.append(f'\nend {NS}\n')
w(D + 'EvData.lean', '\n'.join(out))

# ---------- EvWin* (one import chain) ----------
NWF, NWCH = C['NWF'], C['NWCH']
per = math.ceil(NW / NWF)
for f in range(NWF):
    js = range(f * per, min(NW, (f + 1) * per))
    imp = f'import {PFX}.EvData' if f < NWCH else f'import {PFX}.EvWin{f - NWCH}'
    out = [HDR.format(doc=f'''Kernel checks (`decide +kernel`): the sorted window `win j` equals the literal chunks of
window `j`, for `j = {js[0]}, …, {js[-1]}`. (The files are chained to bound memory use.)'''),
           imp + HEAD + '1000000\nset_option Elab.async false\n']
    for j in js:
        out.append(f'theorem win_eq_{j} : win {j} = (evWins.getD {j} []).flatten := by decide +kernel\n')
    out.append(f'end {NS}\n')
    w(D + f'EvWin{f}.lean', '\n'.join(out))

# ---------- EvSorted ----------
out = [HDR.format(doc='''Kernel checks: the concatenated event list is strictly increasing, and no chunk is empty.'''),
       f'import {PFX}.EvData' + HEAD + '1000000\n',
       f'theorem evList_sorted :\n    sortedLT ((List.range {NW}).flatMap (fun j => (evWins.getD j []).flatten) ++ [400]) = true := by\n  decide +kernel\n',
       'theorem evChunks_ne_nil : ∀ c ∈ evChunks, c ≠ [] := by decide +kernel\n',
       f'end {NS}\n']
w(D + 'EvSorted.lean', '\n'.join(out))

# ---------- EvSum* (NCH import chains) ----------
NCH = C['NCH']
NSF = math.ceil(NC / C['SUMPER'])
NSF = max(NCH, NCH * math.ceil(NSF / NCH))
per = math.ceil(NC / NSF)
for f in range(NSF):
    idx = range(f * per, min(NC, (f + 1) * per))
    imp = (f'import {PFX}.EvData\nimport {PFX}.FastG' if f < NCH else f'import {PFX}.EvSum{f - NCH}')
    out = [HDR.format(doc=f'''Kernel checks (`decide +kernel`): the rounded A-certificate body over event chunks
{idx[0]}, …, {idx[-1]} (`termUnitsG`, equal to `termUnits` by `termUnits_eq_G`). The `EvSum*` files
form {NCH} import chains only to bound the number of concurrent builds (memory).'''),
           imp + HEAD + '1000000\nset_option Elab.async false\n']
    for i in idx:
        v = chunks[i][0]
        nxt = f'evC{i+1}.headD 400' if i + 1 < NC else '400'
        out.append(f'theorem evSum_{i} : pairSum termUnitsG (evC{i} ++ [{nxt}]) = {v} := by\n  decide +kernel\n')
    out.append(f'end {NS}\n')
    w(D + f'EvSum{f}.lean', '\n'.join(out))


# ---------- CertCompute ----------
def wrap(items, ind):
    lines, cur = [], ind
    for it in items:
        add = it + ', '
        if len(cur) + len(add) > 99:
            lines.append(cur.rstrip())
            cur = ind
        cur += add
    lines.append(cur.rstrip().rstrip(','))
    return '\n'.join(lines).strip()


imports = ['import ZetaIrrational.Z7.CertA.Cert'] + [f'import {PFX}.EvWin{f}' for f in range(NWF - NWCH, NWF)] + [f'import {PFX}.EvSorted'] + \
          [f'import {PFX}.EvSum{f}' for f in range(NSF)]
s = f'''/-
# The A-certificate for {C['name']}: the rounded body sum, checked by the kernel

`bodyUnits 400` (the body of the A integral: each of the {NEV:,} terms rounded up to a multiple of
`2^-96`, in units of `2^-96`) is evaluated by the kernel; with the tail it gives `Acert` exactly
(`certFact_of_units`, `Z7/CertA/Cert.lean`).

Everything is checked by the kernel (`decide +kernel`); no `native_decide`:
* `events 400 = evChunks.flatten ++ [400]` (`events_400_eq`): each of the {NW} windows `win j` is
  sorted in the kernel and compared with its literal chunks (`EvWin*.lean`); the concatenation is
  strictly increasing (`EvSorted.lean`); then `events_eq_of_windows` (`Windows.lean`) identifies
  it with `events 400` (whose `List.mergeSort` the kernel cannot reduce).
* `termUnits = termUnitsG` (`FastG.lean`): a closed form of `e*` that the kernel
  evaluates quickly (`Nat` primitives per block).
* `pairSum` splits over the {NC} chunks (`pairSum_flatten`); each chunk sum is one
  `decide +kernel` lemma (`EvSum*.lean`).

The literal data (`EvData.lean`) and the chunk values were generated by `#eval`
(`scripts/certA/`, see TRUST.md); none of it is trusted. This file is generated too.
-/
{chr(10).join(imports)}

namespace {NS}

set_option maxRecDepth 1000000

theorem win_eq_all : ∀ j < {NW}, win j = (evWins.getD j []).flatten := by
  intro j hj
  interval_cases j
  exacts [{wrap([f'win_eq_{j}' for j in range(NW)], '    ')}]

/-- The event list as literal chunks. -/
theorem events_400_eq : events 400 = evChunks.flatten ++ [400] := by
  rw [events_eq_of_windows _ win_eq_all evList_sorted]
  have h := flatMap_range_getD evWins
  rw [evWins_length, evWins_flatten] at h
  rw [h]

/-- **The rounded body sum, computed by the kernel.** -/
theorem bodyUnits_400 : bodyUnits 400 = {C['total']} := by
  unfold bodyUnits
  rw [termUnits_eq_G, events_400_eq, pairSum_flatten _ _ _ evChunks_ne_nil]
  simp only [evChunks, chunkSums, nextHead,
    {wrap([f'evSum_{i}' for i in range(NC)], '    ')}]
  norm_num

end {NS}
'''
w(D + 'CertCompute.lean', s)
print(f'{inst}: {NEV} events, {NC} chunks, {NWF} EvWin files, {NSF} EvSum files; total {total}')
